/**
 * importar_nazari_data.js
 * Script de importación única: sube todos los eventos, noticias y entrevistas
 * de la web estática de Editorial Nazarí a Firestore.
 *
 * Uso:
 *   cd functions
 *   node importar_nazari_data.js
 *
 * Requiere: firebase-admin (ya instalado en functions/)
 * Credenciales: usa GOOGLE_APPLICATION_CREDENTIALS o Application Default Credentials
 * (ejecutar antes: firebase login && firebase use planeaapp-4bea4)
 */

const admin = require('firebase-admin');
const fs    = require('fs');
const path  = require('path');
const os    = require('os');

// ── Credential: Firebase CLI stored refresh token ─────────────────────────────
function getRefreshToken() {
  const candidates = [
    path.join(os.homedir(), '.config', 'configstore', 'firebase-tools.json'),
    path.join(process.env.APPDATA || '', 'Roaming', 'configstore', 'firebase-tools.json'),
    path.join(process.env.APPDATA || '', 'configstore', 'firebase-tools.json'),
  ];
  for (const p of candidates) {
    try {
      const d = JSON.parse(fs.readFileSync(p, 'utf8'));
      const rt = d?.tokens?.refresh_token;
      if (rt) return rt;
    } catch (_) {}
  }
  return null;
}

const refreshToken = getRefreshToken();
if (!refreshToken) {
  console.error('❌ No se encontró el token de Firebase CLI. Ejecuta "firebase login" primero.');
  process.exit(1);
}

