// ── Helpers ───────────────────────────────────────────────────────────────────
function parseFecha(str) {
  // Acepta 'YYYY-MM-DD' o 'YYYY-MM-DDTHH:MM:SS...'
  const d = new Date(str + (str.length === 10 ? 'T12:00:00' : ''));
  return isNaN(d.getTime()) ? new Date() : d;
}

function tipoEventoLabel(raw) {
  const map = {
    'presentacion': 'Presentación',
    'presentación': 'Presentación',
    'presentacion': 'Presentación',
    'firma':        'Presentación', // la app trata Firma como Presentación (TipoEventoExt.fromId)
    'feria':        'Feria',
    'taller':       'Taller',
    'lectura':      'Lectura',
    'conferencia':  'Evento',
    'premio':       'Evento',
  };
  if (!raw) return 'Presentación';
  return map[raw.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'')]
      || raw; // ya viene capitalizado
}

async function uploadBatch(colRef, docs, label) {
  let batch = db.batch();
  let count = 0;
  let total = 0;
  for (const [id, data] of docs) {
    batch.set(colRef.doc(id), data, { merge: true });
    count++;
    total++;
    if (count === 400) { // máx 500 por batch; usamos 400 para margen
      await batch.commit();
      batch = db.batch();
      count = 0;
      process.stdout.write(`  ${label}: ${total} subidos...\r`);
    }
  }
  if (count > 0) await batch.commit();
  console.log(`  ✅ ${label}: ${total} documentos importados`);
}

