// ─────────────────────────────────────────────────────────────────────────────
// IMPORT
// ─────────────────────────────────────────────────────────────────────────────
async function main() {
  console.log('🚀 Iniciando importación de datos Nazarí a Firestore...\n');

  // ── Eventos ──────────────────────────────────────────────────────────────
  const eventoDocs = EVENTOS_RAW.map(ev => {
    const fecha = parseFecha(ev.fecha);
    const tipo  = tipoEventoLabel(ev.tipo);
    const doc = {
      titulo:      ev.titulo,
      subtitulo:   ev.subtitulo || '',
      descripcion: ev.descripcion || '',
      fecha:       admin.firestore.Timestamp.fromDate(fecha),
      lugar:       ev.lugar || '',
      ciudad:      ev.ciudad || '',
      tipo:        tipo,
      activo:      true,
      eliminado:   false,
      _importado:  true,
      _fuente:     'eventos-data.js',
    };
    if (ev.hora)          doc.hora         = ev.hora;
    if (ev.imagen)        { doc.imagen_url = ev.imagen; doc.imagen = ev.imagen; }
    if (ev.autor_nombre)  doc.autor_nombre = ev.autor_nombre;
    return [ev.id, doc];
  });

  await uploadBatch(colBase.collection('eventos'), eventoDocs, 'Eventos');

  // ── Blog (Entrevistas + Noticias) ─────────────────────────────────────────
  const blogDocs = BLOG_RAW.map(p => {
    const fecha = parseFecha(p.fecha);
    const doc = {
      titulo:            p.titulo,
      slug:              p.slug,
      resumen:           p.resumen || '',
      contenido:         '',
      autor:             p.autor || '',
      categoria_id:      p.tipo === 'entrevista' ? 'Entrevistas' : 'Noticias',
      tipo:              p.tipo,  // 'entrevista' | 'noticia'
      estado:            'publicado',
      publicada:         true,
      fecha_publicacion: admin.firestore.Timestamp.fromDate(fecha),
      etiquetas:         [],
      imagenes:          [],
      destacado:         false,
      visitas:           0,
      eliminado:         false,
      seo:               { meta_title: '', meta_description: '', keywords: [] },
      _importado:        true,
      _fuente:           'blog.html',
    };
    if (p.imagen_url)    doc.imagen_url  = p.imagen_url;
    if (p.url_externa)   doc.url_externa = p.url_externa;
    return [p.id, doc];
  });

  await uploadBatch(colBase.collection('blog'), blogDocs, 'Blog (noticias + entrevistas)');

  console.log('\n✅ Importación completada.');
  console.log(`   ${EVENTOS_RAW.length} eventos  →  empresas/${EID}/eventos`);
  console.log(`   ${BLOG_RAW.length} entradas  →  empresas/${EID}/blog`);
  console.log('\nLos datos ya son visibles en el módulo web de la app Flutter y en la web de Nazarí.');
  process.exit(0);
}

main().catch(err => {
  console.error('❌ Error en la importación:', err.message || err);
  process.exit(1);
});
